1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	
5	/**
6	 * Hero deploy terminal (v8) — types a real `nxeon deploy` command, streams the
7	 * provisioning steps, and resolves to "online in 47s" (the speed hook the brief
8	 * calls out as the strongest buying trigger). Loops. Pure JS/CSS, no assets,
9	 * reduced-motion → the finished state.
10	 */
11	const CMD = "nxeon deploy --plan pro --os ubuntu";
12	const STEPS: { t: string; tone: "muted" | "ok" | "accent" }[] = [
13	  { t: "→ Provisioning NVMe SSD instance…", tone: "muted" },
14	  { t: "→ Configuring DDoS protection layer…", tone: "muted" },
15	  { t: "→ Installing OS · Ubuntu 24.04 LTS…", tone: "muted" },
16	  { t: "→ Assigning IPv4 · IPv6 addresses…", tone: "muted" },
17	  { t: "✓ Server online in 47s", tone: "ok" },
18	  { t: "  ssh root@51.79.162.96 -p 20114", tone: "accent" },
19	];
20	const TONE = { muted: "text-slate-400", ok: "text-emerald-300 font-semibold", accent: "text-accent-cyan" };
21	
22	export function DeployCard() {
23	  const [typed, setTyped] = useState("");
24	  const [shown, setShown] = useState(0);
25	  const [phase, setPhase] = useState<"type" | "run" | "done">("type");
26	  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
27	
28	  useEffect(() => {
29	    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
30	    if (reduce) { setTyped(CMD); setShown(STEPS.length); setPhase("done"); return; }
31	    let dead = false;
32	    const push = (fn: () => void, ms: number) => { if (!dead) timers.current.push(setTimeout(fn, ms)); };
33	    const run = () => {
34	      setTyped(""); setShown(0); setPhase("type");
35	      CMD.split("").forEach((_, i) => push(() => setTyped(CMD.slice(0, i + 1)), 55 * i + 300));
36	      const afterType = 55 * CMD.length + 600;
37	      push(() => setPhase("run"), afterType);
38	      STEPS.forEach((_, i) => push(() => setShown(i + 1), afterType + 520 * (i + 1)));
39	      push(() => setPhase("done"), afterType + 520 * (STEPS.length + 1));
40	      push(run, afterType + 520 * (STEPS.length + 1) + 3200); // loop
41	    };
42	    run();
43	    return () => { dead = true; timers.current.forEach(clearTimeout); timers.current = []; };
44	  }, []);
45	
46	  return (
47	    <div className="glass overflow-hidden rounded-2xl border-white/10 shadow-2xl glow-brand">
48	      <div className="flex items-center gap-1.5 border-b border-white/[0.06] px-4 py-2.5">
49	        <span className="h-2.5 w-2.5 rounded-full bg-red-500/70" />
50	        <span className="h-2.5 w-2.5 rounded-full bg-amber-400/70" />
51	        <span className="h-2.5 w-2.5 rounded-full bg-emerald-400/70" />
52	        <span className="ml-2 font-mono text-[11px] uppercase tracking-widest text-slate-500">nxeon · deploy</span>
53	        <span className="ml-auto rounded-md border border-accent-cyan/30 bg-accent-cyan/10 px-2 py-0.5 font-mono text-[10px] text-accent-cyan">47s</span>
54	      </div>
55	      <div className="h-[272px] space-y-1.5 overflow-hidden p-4 font-mono text-[13px] leading-relaxed">
56	        <div className="text-slate-200">
57	          <span className="text-accent-cyan">$</span> {typed}
58	          {phase === "type" && <span className="ml-0.5 inline-block h-3.5 w-[7px] bg-accent-cyan align-middle [animation:blink_1s_step-end_infinite]" />}
59	        </div>
60	        {STEPS.slice(0, shown).map((s, i) => <div key={i} className={TONE[s.tone]}>{s.t}</div>)}
61	        {phase === "done" && (
62	          <div className="mt-3 flex items-center gap-2 rounded-lg border border-emerald-400/20 bg-emerald-400/[0.06] px-3 py-2 text-xs text-emerald-300">
63	            <span className="relative flex h-2 w-2"><span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-emerald-400/70" /><span className="relative inline-flex h-2 w-2 rounded-full bg-emerald-400" /></span>
64	            web-prod-01 is live · 99.9% uptime SLA
65	          </div>
66	        )}
67	      </div>
68	    </div>
69	  );
70	}
