1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	
5	/**
6	 * The "Matrix operational" console — a looping stream of a real Nxeon deploy
7	 * sequence, typed line by line. Pure CSS/JS, no assets. Respects reduced motion
8	 * (shows the finished list at once).
9	 */
10	const LINES: { t: string; s?: string }[] = [
11	  { t: "initiating matrix" },
12	  { t: "spinning up agents", s: "3,734 online" },
13	  { t: "provisioning server", s: "nvme · 4 vcpu" },
14	  { t: "installing runtime", s: "node 22" },
15	  { t: "configuring ssl", s: "issued" },
16	  { t: "pointing dns", s: "resolved" },
17	  { t: "deploying app", s: "live" },
18	  { t: "matrix operational", s: "" },
19	];
20	
21	export function MatrixTerminal() {
22	  const [shown, setShown] = useState(0);
23	  const reduce = useRef(false);
24	
25	  useEffect(() => {
26	    reduce.current = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
27	    if (reduce.current) { setShown(LINES.length); return; }
28	    let i = 0;
29	    let timer: ReturnType<typeof setTimeout>;
30	    const tick = () => {
31	      i = i >= LINES.length ? 0 : i;
32	      setShown(i + 1);
33	      i += 1;
34	      timer = setTimeout(tick, i > LINES.length ? 2200 : 620);
35	    };
36	    timer = setTimeout(tick, 400);
37	    return () => clearTimeout(timer);
38	  }, []);
39	
40	  return (
41	    <div className="rounded-2xl border border-white/10 bg-black/60 p-5 font-mono text-[13px] shadow-2xl backdrop-blur-sm">
42	      <div className="mb-3 flex items-center gap-1.5">
43	        <span className="h-2.5 w-2.5 rounded-full bg-red-500/70" />
44	        <span className="h-2.5 w-2.5 rounded-full bg-amber-400/70" />
45	        <span className="h-2.5 w-2.5 rounded-full bg-emerald-400/70" />
46	        <span className="ml-2 text-[11px] uppercase tracking-widest text-slate-500">nxeon · matrix</span>
47	      </div>
48	      <div className="min-h-[196px] space-y-1.5">
49	        {LINES.slice(0, shown).map((l, i) => {
50	          const done = l.t === "matrix operational";
51	          return (
52	            <div key={i} className="flex items-center justify-between gap-4">
53	              <span className={done ? "font-semibold text-brand-300" : "text-slate-300"}>
54	                <span className="text-brand-400">&gt;</span> {l.t}
55	              </span>
56	              {l.s !== undefined && (
57	                <span className={done ? "text-brand-300" : l.s ? "text-emerald-400" : "text-slate-500"}>{l.s || "…"}</span>
58	              )}
59	            </div>
60	          );
61	        })}
62	        {shown < LINES.length && <span className="inline-block h-3 w-2 animate-pulse bg-brand-400 align-middle" />}
63	      </div>
64	    </div>
65	  );
66	}
