1	/**
2	 * "Global network" band (v7/v8) — a real DOTTED WORLD MAP (continents rendered as
3	 * dot clusters from continent footprints) with labelled PoP nodes on true-ish
4	 * geography, linked by brand-gradient arcs with travelling data pulses. Framed in
5	 * a console panel so it reads as a deliberate visualization, not floating dots.
6	 * Pure SVG + scoped CSS, deterministic (SSR-safe), no assets.
7	 */
8	const W = 1000, H = 460;
9	
10	// continent footprints (equirectangular-ish ellipses on the viewBox)
11	const LAND = [
12	  { cx: 205, cy: 150, rx: 120, ry: 92 },  // North America
13	  { cx: 300, cy: 335, rx: 52, ry: 92 },   // South America
14	  { cx: 355, cy: 70, rx: 42, ry: 34 },    // Greenland
15	  { cx: 520, cy: 128, rx: 55, ry: 52 },   // Europe
16	  { cx: 548, cy: 275, rx: 72, ry: 100 },  // Africa
17	  { cx: 730, cy: 150, rx: 168, ry: 98 },  // Asia
18	  { cx: 800, cy: 300, rx: 40, ry: 34 },   // SE Asia / Indonesia
19	  { cx: 878, cy: 352, rx: 58, ry: 40 },   // Australia
20	];
21	const noise = (i: number, j: number) => { const s = Math.sin(i * 12.9898 + j * 78.233) * 43758.5453; return s - Math.floor(s); };
22	
23	function landDots() {
24	  const dots: { x: number; y: number; o: number }[] = [];
25	  const step = 13;
26	  for (let x = step; x < W; x += step) {
27	    for (let y = 30; y < H - 20; y += step) {
28	      let best = 2;
29	      for (const c of LAND) { const t = ((x - c.cx) / c.rx) ** 2 + ((y - c.cy) / c.ry) ** 2; if (t < best) best = t; }
30	      const n = noise(x, y);
31	      if (best < 0.88 || (best < 1 && n > 0.55)) dots.push({ x: x + (n - 0.5) * 4, y: y + (noise(y, x) - 0.5) * 4, o: 0.22 + (1 - best) * 0.3 });
32	    }
33	  }
34	  return dots;
35	}
36	
37	const CITIES = [
38	  { name: "Toronto", x: 232, y: 150 }, { name: "New York", x: 258, y: 176 },
39	  { name: "Amsterdam", x: 520, y: 116 }, { name: "Frankfurt", x: 545, y: 132 },
40	  { name: "Singapore", x: 790, y: 300 }, { name: "Tokyo", x: 848, y: 158 },
41	  { name: "Sydney", x: 888, y: 350 },
42	];
43	const LINKS: [number, number][] = [[1, 2], [0, 1], [3, 4], [2, 3], [4, 5], [4, 6], [5, 6], [1, 3]];
44	const arcPath = (a: { x: number; y: number }, b: { x: number; y: number }) => {
45	  const mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2 - Math.hypot(a.x - b.x, a.y - b.y) * 0.26;
46	  return `M${a.x},${a.y} Q${mx},${my} ${b.x},${b.y}`;
47	};
48	
49	export function NetworkMap() {
50	  const dots = landDots();
51	  return (
52	    <div className="relative overflow-hidden rounded-2xl border border-white/[0.08] bg-navy-950/60 glow-brand">
53	      <style>{`
54	        @keyframes nm-pulse { 0%{offset-distance:0%;opacity:0} 12%{opacity:1} 88%{opacity:1} 100%{offset-distance:100%;opacity:0} }
55	        @keyframes nm-blip { 0%,100%{opacity:.5} 50%{opacity:1} }
56	        @media (prefers-reduced-motion: reduce){ .nm-pulse{animation:none!important;opacity:0} }
57	      `}</style>
58	      {/* header */}
59	      <div className="flex items-center justify-between border-b border-white/[0.06] px-4 py-2.5 font-mono text-[11px]">
60	        <span className="flex items-center gap-2 text-slate-500"><span className="h-1.5 w-1.5 rounded-full bg-emerald-400" /> nxeon · global network</span>
61	        <span className="text-slate-500">7 regions · &lt;10 ms metro latency</span>
62	      </div>
63	      <div className="relative">
64	        <div aria-hidden className="pointer-events-none absolute inset-0 bg-[radial-gradient(ellipse_at_center,rgba(111,71,245,0.10),transparent_70%)]" />
65	        <svg viewBox={`0 0 ${W} ${H}`} className="relative block w-full" role="img" aria-label="Nxeon global network: points of presence across North America, Europe, Asia and Oceania">
66	          <defs>
67	            <linearGradient id="nm-arc" x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stopColor="#3b82f6" /><stop offset="100%" stopColor="#8a70fb" /></linearGradient>
68	            <radialGradient id="nm-node" cx="50%" cy="50%" r="50%"><stop offset="0%" stopColor="#22d3ee" /><stop offset="100%" stopColor="#3b82f6" /></radialGradient>
69	          </defs>
70	
71	          {/* land dots */}
72	          {dots.map((d, i) => <circle key={i} cx={d.x} cy={d.y} r={1.1} fill={`rgba(120,150,220,${d.o})`} />)}
73	
74	          {/* arcs + pulses */}
75	          {LINKS.map(([i, j], k) => {
76	            const d = arcPath(CITIES[i], CITIES[j]);
77	            return (
78	              <g key={k}>
79	                <path d={d} fill="none" stroke="url(#nm-arc)" strokeWidth="1.2" opacity="0.5" />
80	                <circle className="nm-pulse" r="2.6" fill="#22d3ee" style={{ offsetPath: `path('${d}')`, animation: `nm-pulse ${3.2 + k * 0.3}s ${k * 0.45}s linear infinite` }} />
81	              </g>
82	            );
83	          })}
84	
85	          {/* city nodes */}
86	          {CITIES.map((c, i) => (
87	            <g key={c.name}>
88	              <circle cx={c.x} cy={c.y} r="11" fill="rgba(34,211,238,0.10)" />
89	              <circle cx={c.x} cy={c.y} r="3.4" fill="url(#nm-node)" style={{ animation: `nm-blip ${2.2 + (i % 3) * 0.4}s ease-in-out infinite` }} />
90	              <g transform={`translate(${c.x + 12}, ${c.y - 9})`}>
91	                <rect x="0" y="0" width={c.name.length * 6.8 + 14} height="18" rx="9" fill="rgba(10,16,31,0.9)" stroke="rgba(255,255,255,0.1)" />
92	                <text x="7" y="12.5" fontFamily="ui-monospace,monospace" fontSize="9.5" fill="#cbd5e1">{c.name}</text>
93	              </g>
94	            </g>
95	          ))}
96	        </svg>
97	      </div>
98	    </div>
99	  );
100	}
