import { MarketingHeader } from "@/components/marketing/MarketingHeader";
import { MarketingFooter } from "@/components/marketing/MarketingFooter";
import { PromoBar } from "@/components/marketing/PromoBar";
import VisitTracker from "@/components/VisitTracker";
import { CurrencyProvider } from "@/components/currency/CurrencyContext";
import { resolveDisplayCurrency } from "@/lib/currency-display";

export default async function MarketingLayout({ children }: { children: React.ReactNode }) {
  // Resolve the visitor's DISPLAY currency + FX rates once per request (cookie
  // override → geo header → configured default) and make them available to every
  // price component through context. DISPLAY ONLY — the charge currency stays USD.
  const { currency, rates } = await resolveDisplayCurrency();
  return (
    <CurrencyProvider initialCurrency={currency} rates={rates}>
      <div className="flex min-h-screen flex-col">
        <VisitTracker />
        <PromoBar />
        <MarketingHeader />
        <main className="flex-1">{children}</main>
        <MarketingFooter />
      </div>
    </CurrencyProvider>
  );
}
