 * Specs/prices are ILLUSTRATIVE preview placeholders in the Nxeon KVM range
 * (mirroring the shape of the real configurator). Reviews are illustrative
 * sample content — same honesty status as the shipped <Testimonials/>: no
 * fabricated server counts, no invented locations beyond the real Singapore PoP.
 */

export type ConfigStop = {
  id: string;
  /** Short tier label shown on the preset chip. */
  tier: string;
  ram: number; // GB
  vcpu: number;
  nvme: number; // GB
  bandwidth: number; // TB
  price: string; // display, rendered with trailing /mo
  popular?: boolean;
  /** One-line "who it's for". */
  blurb: string;
};

export type VpsFeature = {
  title: string;
  body: string;
  icon:
    | "terminal"
    | "nvme"
    | "bolt"
    | "scale"
    | "shield"
    | "backup"
    | "globe"
    | "server";
};

export type SpecRow = { k: string; v: string };

export type Review = {
  id: string;
  quote: string;
  name: string;
  meta: string;
  rating: number;
};

/** The interactive configurator stops (also rendered as preset cards). */
export const CONFIG_STOPS: ConfigStop[] = [
