/** Boot sequence typed out by the hero console, resolving to "online in 47s". */
export const BOOT_LINES = [
  "nxeon deploy --plan pro --os ubuntu-24.04 --root",
  "→ allocating  4 GB · 2 vCPU · 100 GB NVMe .... ok",
