"use client";

/**
 * PREVIEW DIRECTION — VPS main landing ("/preview/vps").
 *
 * The flagship core-product page, built to convert. Hero centerpiece is a
 * genuinely-animated deploy console that types `nxeon deploy …`, streams the
 * provisioning steps, and resolves to "✓ online in 47s" with a live telemetry
 * footer — an evolution of DeployCard/MatrixTerminal. Below: an asymmetric
 * buying-story bento, a real product-screen (ServerDashboard), an INTERACTIVE
 * plan configurator (slider + preset cards driving live specs + price), an
 * everything-included spec grid, a NetworkMap latency band, compact 5-star
 * reviews, and the "47 seconds away" close.
 *
 * Net-new + preview-only. Reuses the approved brand tokens, the shipped
 * showcase components, and the gamelanding client kit hooks so it reads as one
 * system. Touches no live page or shared component. Respects reduced motion and
 * is responsive down to 390px.
 */

import Link from "next/link";
import { useEffect, useRef, useState } from "react";
import {
  usePrefersReducedMotion,
  useInViewOnce,
  useJitter,
  StarRow,
} from "@/components/marketing/gamelanding/kit";
import { ServerDashboard } from "@/components/marketing/showcase/ServerDashboard";
import { NetworkMap } from "@/components/marketing/NetworkMap";
import {
  IconTerminal,
  IconNvme,
  IconBolt,
  IconScale,
  IconShield,
  IconBackup,
  IconGlobe,
  IconServer,
  IconCheck,
  IconClock,
  IconNetwork,
  IconLock,
} from "@/components/marketing/icons";
import {
  CONFIG_STOPS,
  FEATURES,
  INCLUDED,
  REVIEWS,
  RATING_AVG,
  RATING_LABEL,
  BOOT_LINES,
  type VpsFeature,
} from "./data";

const FEATURE_ICON: Record<VpsFeature["icon"], (p: { size?: number }) => React.ReactElement> = {
  terminal: IconTerminal,
  nvme: IconNvme,
  bolt: IconBolt,
  scale: IconScale,
  shield: IconShield,
  backup: IconBackup,
  globe: IconGlobe,
  server: IconServer,
};

/* ── HERO: animated deploy console ───────────────────────────────────────── */
function BootConsole() {
  const reduced = usePrefersReducedMotion();
  const cmd = BOOT_LINES[0];
  const steps = BOOT_LINES.slice(1);

  const [typed, setTyped] = useState(reduced ? cmd : "");
  const [shown, setShown] = useState(reduced ? steps.length : 0);
  const [phase, setPhase] = useState<"type" | "run" | "live">(reduced ? "live" : "type");
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);

  const live = phase === "live";
  const cpu = useJitter(34, 5, live, 2200, reduced);
  const ram = useJitter(58, 4, live, 2600, reduced);
  const net = useJitter(128, 14, live, 2000, reduced);

  useEffect(() => {
    if (reduced) return;
    let dead = false;
    const push = (fn: () => void, ms: number) => {
      if (!dead) timers.current.push(setTimeout(fn, ms));
    };
    const run = () => {
      setTyped("");
      setShown(0);
      setPhase("type");
      cmd.split("").forEach((_, i) => push(() => setTyped(cmd.slice(0, i + 1)), 42 * i + 350));
      const afterType = 42 * cmd.length + 650;
      push(() => setPhase("run"), afterType);
      steps.forEach((_, i) => push(() => setShown(i + 1), afterType + 480 * (i + 1)));
      const afterSteps = afterType + 480 * (steps.length + 1);
      push(() => setPhase("live"), afterSteps);
      push(run, afterSteps + 4200); // loop
    };
    run();
    return () => {
      dead = true;
      timers.current.forEach(clearTimeout);
      timers.current = [];
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reduced]);

  const progress = live ? 100 : (shown / steps.length) * 100;

  return (
    <div className={reduced ? "" : "pv-float"}>
      <div className="glass relative overflow-hidden rounded-2xl border-white/10 shadow-2xl glow-brand">
        {/* brand aura */}
        <div
          className="pointer-events-none absolute -inset-16 -z-10 opacity-70"
          style={{
            background:
              "radial-gradient(45% 45% at 82% 0%, rgba(111,71,245,0.28), transparent 70%), radial-gradient(40% 40% at 10% 100%, rgba(34,211,238,0.14), transparent 70%)",
          }}
