/* ── HERO: animated live inbox ───────────────────────────────────────────── */
function LiveInbox() {
  const reduced = usePrefersReducedMotion();
  const initialStart = Math.max(0, INBOX.length - 3);
  const [start, setStart] = useState(reduced ? 0 : initialStart);
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);

  useEffect(() => {
    if (reduced) return;
    let dead = false;
    const push = (fn: () => void, ms: number) => {
      if (!dead) timers.current.push(setTimeout(fn, ms));
    };
    const run = () => {
      setStart(initialStart);
      // prepend newer messages one by one
      for (let s = initialStart - 1, n = 1; s >= 0; s--, n++) {
        const target = s;
        push(() => setStart(target), 1400 * n + 700);
      }
      push(run, 1400 * initialStart + 700 + 3600); // hold, then loop
    };
    run();
    return () => {
      dead = true;
      timers.current.forEach(clearTimeout);
      timers.current = [];
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reduced]);

  const visible = INBOX.map((m, i) => ({ m, i })).slice(start);
  const unread = visible.filter((v) => v.m.unread).length;

  return (
    <div className={reduced ? "" : "pv-float"}>
      <ScreenFrame title="you@yourbrand.com" icon={<IconMail size={13} />} className="glow-brand">
        {/* toolbar with live sender score */}
        <div className="flex items-center justify-between gap-3 border-b border-white/[0.06] bg-white/[0.02] px-4 py-2">
          <span className="inline-flex items-center gap-2 text-[12px] font-medium text-slate-300">
            Inbox
            <span key={unread} className="rounded-full bg-brand-500/15 px-1.5 text-[10px] font-semibold text-brand-200 motion-safe:animate-price-pop">
              {unread} new
            </span>
          </span>
          <span className="inline-flex items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-medium text-emerald-300">
            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
            Sender score 99
          </span>
        </div>

        <ul className="divide-y divide-white/[0.05]">
          {visible.map(({ m, i }) => {
            const fresh = i === start && start < initialStart;
            return (
              <li
                key={i}
                className={`flex items-center gap-3 px-4 py-3 ${fresh ? "bg-brand-500/[0.07] motion-safe:animate-line-in" : ""}`}
              >
                <span className="relative flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-white/[0.05] text-xs font-semibold text-slate-200">
                  {m.from.slice(0, 1)}
                  {m.unread && (
                    <span className="absolute -right-0.5 -top-0.5 h-2.5 w-2.5 rounded-full border-2 border-[#0a0e1a] bg-brand-400 motion-safe:animate-pulse-dot" />
                  )}
                </span>
                <div className="min-w-0 flex-1">
                  <p className={`truncate text-[13px] ${m.unread ? "font-semibold text-white" : "text-slate-300"}`}>
                    {m.from}
                  </p>
                  <p className="truncate text-[12px] text-slate-500">{m.subj}</p>
                </div>
                <span className="shrink-0 text-[11px] text-slate-500">{m.time}</span>
              </li>
            );
          })}
        </ul>

        <div className="flex items-center justify-between border-t border-white/[0.06] px-4 py-2.5 text-[11px] text-slate-500">
          <span className="font-mono">yourbrand.com · verified</span>
          <span className="inline-flex items-center gap-1.5 rounded-lg bg-gradient-to-r from-accent-blue to-brand-500 px-2.5 py-1 text-[11px] font-semibold text-white">
            Compose
          </span>
        </div>
      </ScreenFrame>
    </div>
  );
}

/* ── Deliverability ring + auth checks ───────────────────────────────────── */
function DeliverabilityMeter() {
  const reduced = usePrefersReducedMotion();
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  const val = useCountUp(99, seen, 1400, reduced);
  const r = 52;
  const c = 2 * Math.PI * r;
  const offset = c * (1 - Math.min(1, val / 100));

  return (
    <div ref={ref} className="card">
      <div className="flex items-center gap-6">
        <div className="relative h-[132px] w-[132px] shrink-0">
          <svg viewBox="0 0 132 132" className="h-full w-full -rotate-90">
            <circle cx="66" cy="66" r={r} fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth="9" />
            <circle
              cx="66"
              cy="66"
              r={r}
              fill="none"
              stroke="url(#eml-ring)"
              strokeWidth="9"
              strokeLinecap="round"
              strokeDasharray={c}
              strokeDashoffset={offset}
              className="motion-safe:transition-[stroke-dashoffset] motion-safe:duration-500"
            />
            <defs>
              <linearGradient id="eml-ring" x1="0" y1="0" x2="1" y2="1">
                <stop offset="0%" stopColor="#3b82f6" />
                <stop offset="60%" stopColor="#8a70fb" />
                <stop offset="100%" stopColor="#22d3ee" />
              </linearGradient>
            </defs>
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center">
            <span className="font-mono text-3xl font-bold tabular-nums text-white">{val}%</span>
            <span className="text-[10px] font-medium uppercase tracking-wide text-slate-500">inbox</span>
          </div>
        </div>
        <div>
          <p className="text-sm font-semibold text-white">Inbox placement</p>
          <p className="mt-1 text-sm leading-relaxed text-slate-400">
            Authenticated sending keeps your mail out of the spam folder — where per-seat webmail often leaves
            small-domain senders.
          </p>
        </div>
      </div>

      <div className="mt-6 space-y-2.5 border-t border-white/[0.06] pt-5">
        {AUTH_CHECKS.map((a, i) => (
          <AuthRow key={a.k} k={a.k} v={a.v} seen={seen} reduced={reduced} delay={300 + i * 180} />
        ))}
      </div>
    </div>
  );
}

function AuthRow({ k, v, seen, reduced, delay }: { k: string; v: string; seen: boolean; reduced: boolean; delay: number }) {
  return (
    <div className="flex items-center gap-3">
      <span
        className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-300 ${
          reduced || !seen ? "" : "motion-safe:animate-check-pop"
        }`}
        style={{ animationDelay: `${delay}ms` }}
      >
        <IconCheck size={15} />
      </span>
      <span className="w-14 shrink-0 font-mono text-xs font-semibold text-white">{k}</span>
      <span className="min-w-0 flex-1 truncate font-mono text-[11px] text-slate-500">{v}</span>
      <span className="hidden shrink-0 rounded-full bg-emerald-500/10 px-2 py-0.5 text-[10px] font-medium text-emerald-300 sm:inline">
        verified
      </span>
    </div>
  );
}

