            <p className="mt-4 text-lg leading-relaxed text-slate-400">
              Point your domain once and we add the MX, SPF, DKIM, and DMARC records for you — no copy-pasting cryptic
              strings into a registrar at midnight. If your domain lives on Nxeon already, it&rsquo;s a single click.
            </p>
            <div className="mt-7 grid grid-cols-2 gap-3">
              {[
                { k: "MX", v: "Routed to your mailboxes" },
                { k: "SPF", v: "Authorised senders set" },
                { k: "DKIM", v: "2048-bit key published" },
                { k: "DMARC", v: "Policy + reporting on" },
              ].map((s) => (
                <div key={s.k} className="rounded-xl border border-white/[0.07] bg-navy-900/50 px-4 py-3">
                  <p className="font-mono text-xs font-semibold text-brand-300">{s.k}</p>
                  <p className="mt-0.5 text-sm text-slate-300">{s.v}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* ── PLANS ────────────────────────────────────────────────────────── */}
      <section className="rail py-24">
        <div className="mx-auto max-w-2xl text-center">
          <span className="eyebrow">Plans</span>
          <h2 className="mt-3 text-3xl font-bold tracking-tight text-white sm:text-4xl">Pick a mailbox size</h2>
          <p className="mt-4 text-lg text-slate-400">
