              style={p.popular ? { boxShadow: "0 0 0 1px rgba(111,71,245,0.4), 0 24px 60px -24px rgba(111,71,245,0.6)" } : undefined}
            >
              {p.popular && (
                <span className="absolute -top-3 left-6 rounded-full bg-gradient-to-r from-accent-blue to-brand-500 px-3 py-1 text-[11px] font-semibold uppercase tracking-wider text-white">
