                </span>
              )}
              <p className="text-xs font-semibold uppercase tracking-wider text-brand-300">{p.tier}</p>
              <p className="mt-2">
                <span className="text-4xl font-bold text-white">{p.price}</span>
                <span className="text-sm text-slate-500">/mailbox/mo</span>
