            </div>
          ))}
        </div>
      </section>

      {/* ── REVIEWS ──────────────────────────────────────────────────────── */}
      <section className="tone-panel py-24">
        <div className="rail">
          <div className="mx-auto max-w-2xl text-center">
            <div className="flex items-center justify-center gap-3">
              <StarRow rating={5} size="text-base" />
              <span className="text-sm text-slate-400">
                <span className="font-semibold text-white">{RATING_AVG} / 5</span> average
              </span>
            </div>
            <h2 className="mt-4 text-3xl font-bold tracking-tight text-white sm:text-4xl">{RATING_LABEL}</h2>
          </div>
          <div className="mt-12 grid gap-4 md:grid-cols-3">
            {REVIEWS.map((rv) => (
              <figure key={rv.id} className="card flex flex-col">
                <StarRow rating={rv.rating} />
                <blockquote className="mt-4 flex-1 text-sm leading-relaxed text-slate-300">
                  &ldquo;{rv.quote}&rdquo;
                </blockquote>
                <figcaption className="mt-5 flex items-center gap-3 border-t border-white/[0.06] pt-4">
                  <span className="flex h-9 w-9 items-center justify-center rounded-full bg-gradient-to-br from-brand-500 to-accent-blue text-sm font-semibold text-white">
                    {rv.name.charAt(0).toUpperCase()}
                  </span>
                  <span>
                    <span className="block text-sm font-semibold text-white">{rv.name}</span>
                    <span className="block text-xs text-slate-500">{rv.meta}</span>
                  </span>
                </figcaption>
              </figure>
            ))}
          </div>
        </div>
      </section>

      {/* ── CTA ──────────────────────────────────────────────────────────── */}
      <section className="relative isolate overflow-hidden py-28">
        <div className="pointer-events-none absolute inset-0 -z-10 hero-aura" aria-hidden />
        <div className="rail text-center">
          <h2 className="mx-auto max-w-3xl text-3xl font-bold tracking-tight text-white sm:text-5xl">
            Give every teammate a <span className="grad-text">@yourcompany.com</span> inbox.
          </h2>
          <p className="mx-auto mt-5 max-w-xl text-lg text-slate-300">
            Bring your domain, we verify the sender records, and your team is sending — inbox-placed — today.
          </p>
          <div className="mt-9 flex flex-wrap justify-center gap-3">
            <Link href="/business-email" className="btn-deploy px-7 py-3.5 text-base">
              Get business email
              <span className="dep-arrow" aria-hidden>→</span>
            </Link>
            <Link href="/pricing" className="btn-secondary px-6 py-3.5 text-base">
              See all pricing
            </Link>
          </div>
        </div>
      </section>
    </div>
  );
}

