function FeatureTile({ f, featured = false, delay = 0 }: { f: Feature; featured?: boolean; delay?: number }) {
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  const Icon = FEATURE_ICON[f.icon];
  return (
    <div
      ref={ref}
      className={`group relative flex flex-col overflow-hidden rounded-2xl border border-white/[0.07] bg-navy-900/60 backdrop-blur-md transition-all duration-700 ease-out hover:border-brand-500/30 ${
        featured ? "h-full p-8" : "p-6"
      } ${seen ? "translate-y-0 opacity-100" : "translate-y-4 opacity-0"}`}
      style={{ transitionDelay: `${delay}ms` }}
    >
      {featured && (
        <div className="pointer-events-none absolute -right-10 -top-10 h-56 w-56 rounded-full bg-brand-500/15 opacity-60 blur-3xl" aria-hidden />
      )}
      <span
        className="flex items-center justify-center rounded-xl border border-white/10 bg-gradient-to-br from-brand-500/25 to-transparent text-brand-300"
        style={{ width: featured ? 52 : 44, height: featured ? 52 : 44 }}
      >
        <Icon size={featured ? 26 : 20} />
      </span>
      <h3 className={`mt-5 font-semibold text-white ${featured ? "text-2xl sm:text-3xl" : "text-lg"}`}>{f.title}</h3>
      <p className={`mt-2 leading-relaxed text-slate-400 ${featured ? "max-w-md text-base" : "text-sm"}`}>{f.body}</p>
      {featured && (
        <div className="mt-auto pt-8">
          <div className="inline-flex items-center gap-2.5 rounded-xl border border-white/10 bg-white/[0.03] px-4 py-2.5">
            <span className="relative flex h-2 w-2">
              <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-accent-cyan/60 motion-reduce:hidden" />
              <span className="relative inline-flex h-2 w-2 rounded-full bg-accent-cyan" />
            </span>
            <span className="text-sm text-slate-300">
              Authenticated the moment your domain connects
            </span>
          </div>
        </div>
      )}
    </div>
  );
}

